package org.sleepwell.app;
import android.app.*;import android.content.*;import android.graphics.Rect;import android.os.*;import android.view.*;import android.widget.*;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.uiautomator.UiDevice;import org.junit.Test;import java.io.File;import java.time.*;import java.util.*;import static org.junit.Assert.*;
/** Actual local search and record navigation, with private saved data and no outputs. */
public final class SearchFlowTest {
    final Instrumentation i=InstrumentationRegistry.getInstrumentation();final Context c=i.getTargetContext();final UiDevice d=UiDevice.getInstance(i);SearchActivity activity;RecordReportActivity report;
    void await(java.util.function.BooleanSupplier condition)throws Exception{long end=SystemClock.elapsedRealtime()+8000;while(!condition.getAsBoolean()&&SystemClock.elapsedRealtime()<end)Thread.sleep(20);assertTrue("Search state ready",condition.getAsBoolean());}
    View find(View root,String text){if(text.contentEquals(root.getContentDescription()==null?"":root.getContentDescription())||root instanceof TextView&&text.contentEquals(((TextView)root).getText()))return root;if(root instanceof ViewGroup group)for(int n=0;n<group.getChildCount();n++){View view=find(group.getChildAt(n),text);if(view!=null)return view;}return null;}
    boolean shown(String text){boolean[] yes={false};i.runOnMainSync(()->yes[0]=activity!=null&&activity.hasWindowFocus()&&find(activity.getWindow().getDecorView(),text)!=null);return yes[0];}
    void query(String value)throws Exception{i.runOnMainSync(()->{View root=activity.getWindow().getDecorView(),field=find(root,"Search settings query");if(field==null)field=find(root,"Search query");((EditText)field).setText(value);});}
    void click(String text)throws Exception{await(()->shown(text));Rect[] bounds={null};i.runOnMainSync(()->{View view=find(activity.getWindow().getDecorView(),text);while(!view.isClickable()&&view.getParent() instanceof View)view=(View)view.getParent();assertTrue(view.isEnabled()&&view.isClickable());Rect visible=new Rect();assertTrue(view.getGlobalVisibleRect(visible));assertEquals(view.getHeight(),visible.height());assertTrue(view.getHeight()>=Design.dp(c,48));int[] pos=new int[2];view.getLocationOnScreen(pos);bounds[0]=new Rect(pos[0],pos[1],pos[0]+view.getWidth(),pos[1]+view.getHeight());});assertTrue(d.click(bounds[0].centerX(),bounds[0].centerY()));}
    void capture(String frame)throws Exception{String expected=switch(frame){case "empty"->"Search your alarms, sleep records and settings.";case "room"->"All settings · 1 result";case "no-results"->"No matching results";case "record","recreated"->"1 result";default->throw new AssertionError("Unknown search frame");};await(()->shown(expected));i.waitForIdleSync();ownedFrame(activity);assertTrue("Exact state before capture: "+frame,shown(expected));File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());assertTrue(d.takeScreenshot(new File(folder,"search-"+frame+".png")));assertTrue("Exact state after capture: "+frame,shown(expected));}
    void ownedFrame(Activity owner)throws Exception{java.util.concurrent.CountDownLatch committed=new java.util.concurrent.CountDownLatch(1);i.runOnMainSync(()->{View root=owner.getWindow().getDecorView();assertTrue(root.hasWindowFocus()&&root.isAttachedToWindow()&&root.isHardwareAccelerated());root.getViewTreeObserver().registerFrameCommitCallback(committed::countDown);root.invalidate();});assertTrue(committed.await(5,java.util.concurrent.TimeUnit.SECONDS));i.runOnMainSync(()->assertTrue(owner.hasWindowFocus()));}
    Switch roomToggle(View root,String name){if(root instanceof Switch toggle&&name.contentEquals(toggle.getContentDescription()))return toggle;if(root instanceof ViewGroup group)for(int n=0;n<group.getChildCount();n++){Switch found=roomToggle(group.getChildAt(n),name);if(found!=null)return found;}return null;}
    void roomDiscovery()throws Exception{
        RoomLightPort.Factory light=RoomConditionsActivity.lights;RoomSoundLevel.Factory audio=RoomConditionsActivity.microphones;RoomConditionsActivity.Access access=RoomConditionsActivity.access;Map<String,?> before=new HashMap<>(Prefs.of(c).getAll());List<RoomConditionsActivity> owned=new ArrayList<>();assertNull(RoomSoundLevel.current());assertFalse(MicrophoneLease.occupied());
        try{
            assertTrue(Prefs.of(c).edit().putBoolean(RoomDimming.ENABLED,false).commit());i.runOnMainSync(()->{RoomConditionsActivity.lights=context->new RoomLightPort(){public boolean available(){return false;}public boolean begin(Sink sink){throw new AssertionError("No physical light registration");}public void close(){}};RoomConditionsActivity.microphones=(context,current)->{throw new AssertionError("No microphone capture from search navigation");};RoomConditionsActivity.access=new RoomConditionsActivity.Access(){public boolean microphone(Context context){return false;}public void request(Activity owner,androidx.activity.result.ActivityResultLauncher<String> launcher){throw new AssertionError("No permission request from search navigation");}};});
            click("Settings only");await(()->shown("Search settings"));for(String term:new String[]{"ambient light","room sound level","screen dimming"}){query("room search fixture no match");await(()->shown("No matching settings · try another term or category"));query(term);await(()->shown("Room conditions"));await(()->shown("All settings · 1 result"));}await(()->shown("Settings › Sleep & bedtime › Room conditions\nLive light, optional sound level and screen dimming"));ownedFrame(activity);capture("room");
            Instrumentation.ActivityMonitor monitor=i.addMonitor(RoomConditionsActivity.class.getName(),null,false);RoomConditionsActivity room;try{click("Room conditions");room=(RoomConditionsActivity)monitor.waitForActivityWithTimeout(5000);assertNotNull(room);owned.add(room);}finally{i.removeMonitor(monitor);}assertEquals(new ComponentName(c,RoomConditionsActivity.class),room.getIntent().getComponent());assertTrue(room.getIntent().getBooleanExtra("visualReview",false));await(room::hasWindowFocus);ownedFrame(room);Rect hit=new Rect();i.runOnMainSync(()->{View root=room.getWindow().getDecorView();Switch microphone=roomToggle(root,"Microphone analysis"),dimming=roomToggle(root,"Screen dimming");assertNotNull(microphone);assertNotNull(dimming);assertFalse(microphone.isChecked());assertFalse(dimming.isChecked());assertTrue(dimming.isEnabled()&&dimming.getGlobalVisibleRect(hit));assertEquals(dimming.getWidth(),hit.width());assertEquals(dimming.getHeight(),hit.height());assertTrue(hit.width()>=Design.dp(c,48)&&hit.height()>=Design.dp(c,48));});assertTrue(d.click(hit.centerX(),hit.centerY()));assertFalse("Draft toggle cannot save dimming",RoomDimming.enabled(c));assertNull(RoomSoundLevel.current());
            monitor=i.addMonitor(RoomConditionsActivity.class.getName(),null,false);RoomConditionsActivity recreated;try{i.runOnMainSync(room::recreate);recreated=(RoomConditionsActivity)monitor.waitForActivityWithTimeout(5000);assertNotNull(recreated);owned.add(recreated);}finally{i.removeMonitor(monitor);}await(room::isDestroyed);await(recreated::hasWindowFocus);ownedFrame(recreated);i.runOnMainSync(()->{View root=recreated.getWindow().getDecorView();assertTrue((roomToggle(root,"Screen dimming")).isChecked());assertFalse((roomToggle(root,"Microphone analysis")).isChecked());});assertFalse(RoomDimming.enabled(c));d.pressBack();await(recreated::isDestroyed);await(()->shown("Room conditions"));i.runOnMainSync(()->assertEquals("screen dimming",((EditText)find(activity.getWindow().getDecorView(),"Search settings query")).getText().toString()));assertFalse("Back discards the unsaved dimming choice",RoomDimming.enabled(c));assertNull(RoomSoundLevel.current());assertFalse(MicrophoneLease.occupied());click("Search everything");await(()->shown("Search SleepWell"));
        }finally{
            try{i.runOnMainSync(()->{for(RoomConditionsActivity room:owned)if(!room.isDestroyed())room.finish();});await(()->owned.stream().allMatch(Activity::isDestroyed));assertNull(RoomSoundLevel.current());assertFalse(MicrophoneLease.occupied());}
            finally{i.runOnMainSync(()->{RoomConditionsActivity.lights=light;RoomConditionsActivity.microphones=audio;RoomConditionsActivity.access=access;});SharedPreferences.Editor restore=Prefs.of(c).edit();if(before.containsKey(RoomDimming.ENABLED))restore.putBoolean(RoomDimming.ENABLED,(Boolean)before.get(RoomDimming.ENABLED));else restore.remove(RoomDimming.ENABLED);assertTrue(restore.commit());assertEquals(before,Prefs.of(c).getAll());}
        }
    }
    @Test public void queryResultsRecreationAndSavedRecordOpenUseRealControls()throws Exception{
        assertEquals("true",InstrumentationRegistry.getArguments().getString("ciReview"));assertEquals("1",d.executeShellCommand("getprop ro.kernel.qemu").trim());assertFalse(AlarmService.active);assertFalse(TrackingService.running);String name="search-ui-"+UUID.randomUUID()+".db";Records.Factory old=Records.factory;Map<String,?> prefs=new HashMap<>(Prefs.of(c).getAll());
        try(Store store=new Store(c,name)){Records.factory=context->new Store(context,name);long now=System.currentTimeMillis();RecordDraft draft=new RecordDraft(now-86400000,now-57600000);String recordQuery="recordsearch"+UUID.randomUUID().toString().replace("-","");draft.note="Evening exercise "+recordQuery;long id=Records.create(store,draft,ZoneId.of("UTC"),now);List<SearchIndex.Entry> index=SearchData.read(c),matching=SearchIndex.find(index,recordQuery);assertEquals("Unique private record identity",1,matching.size());assertEquals(SearchIndex.Kind.RECORD,matching.get(0).kind);assertEquals(id,matching.get(0).id);assertTrue("Exercise is also a real settings alias",SearchIndex.find(index,"exercise").stream().anyMatch(entry->entry.kind==SearchIndex.Kind.SETTING&&entry.title.equals("Tags and quantities")));String before=BackupFingerprint.read(store);Instrumentation.ActivityMonitor monitor=i.addMonitor(SearchActivity.class.getName(),null,false);try{c.startActivity(new Intent(c,SearchActivity.class).putExtra("visualReview",true).putExtra("verificationLabel","Private local search fixture").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));activity=(SearchActivity)monitor.waitForActivityWithTimeout(5000);assertNotNull(activity);}finally{i.removeMonitor(monitor);}await(()->shown("Search your alarms, sleep records and settings."));capture("empty");roomDiscovery();query("nothing-matches");await(()->shown("No matching results"));capture("no-results");query(recordQuery);await(()->shown("1 result"));await(()->shown(RecordUi.date(draft.end,ZoneId.of("UTC"))));capture("record");SearchActivity previous=activity;monitor=i.addMonitor(SearchActivity.class.getName(),null,false);try{i.runOnMainSync(previous::recreate);activity=(SearchActivity)monitor.waitForActivityWithTimeout(5000);assertNotNull(activity);}finally{i.removeMonitor(monitor);}await(()->shown("1 result"));await(()->shown(RecordUi.date(draft.end,ZoneId.of("UTC"))));i.runOnMainSync(()->assertEquals(recordQuery,((EditText)find(activity.getWindow().getDecorView(),"Search query")).getText().toString()));capture("recreated");String title=RecordUi.date(draft.end,ZoneId.of("UTC"));monitor=i.addMonitor(RecordReportActivity.class.getName(),null,false);try{click(title);report=(RecordReportActivity)monitor.waitForActivityWithTimeout(5000);assertNotNull(report);assertEquals(id,report.getIntent().getLongExtra("record",0));}finally{i.removeMonitor(monitor);}report.awaitReaders(8000);assertEquals(before,BackupFingerprint.read(store));assertEquals(prefs,Prefs.of(c).getAll());
        }finally{if(report!=null&&!report.isDestroyed()){RecordReportActivity owned=report;i.runOnMainSync(owned::finish);await(owned::isDestroyed);owned.awaitReaders(8000);}if(activity!=null&&!activity.isDestroyed()){SearchActivity owned=activity;i.runOnMainSync(owned::finish);await(owned::isDestroyed);assertTrue(owned.awaitReaders(8000));}Records.factory=old;assertTrue(c.deleteDatabase(name));assertFalse(AlarmService.active);assertFalse(TrackingService.running);assertEquals(prefs,Prefs.of(c).getAll());}
    }
}
